export type ParsedRequestDepositInstruction<
  TProgram extends string = typeof NTBUNDLE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    user: TAccountMetas[0];
    /** user token account (source of funds) */
    userTokenAccount: TAccountMetas[1];
    pendingDepositTokenAccount: TAccountMetas[2];
    treasuryAccount: TAccountMetas[3];
    userBundleAccount: TAccountMetas[4];
    assetAddress: TAccountMetas[5];
    oracleData: TAccountMetas[6];
    bundleTempData: TAccountMetas[7];
    bundleAccount: TAccountMetas[8];
    pendingBundleAssetAuthority: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
    systemProgram: TAccountMetas[11];
  };
  data: RequestDepositInstructionData;
};

export function parseRequestDepositInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRequestDepositInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      userTokenAccount: getNextAccount(),
      pendingDepositTokenAccount: getNextAccount(),
      treasuryAccount: getNextAccount(),
      userBundleAccount: getNextAccount(),
      assetAddress: getNextAccount(),
      oracleData: getNextAccount(),
      bundleTempData: getNextAccount(),
      bundleAccount: getNextAccount(),
      pendingBundleAssetAuthority: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getRequestDepositInstructionDataDecoder().decode(instruction.data),
  };
}
